{
  "summary": "The function fn_03 computes a custom checksum using a linear congruential generator (LCG) algorithm.",
  "proposed_name": "fn_03",
  "algorithm": "unknown",
  "self_confidence": 0.95,
  "claims": [
    {
      "id": "1",
      "type": "ALG",
      "text": "Implements a linear congruential generator (LCG) algorithm.",
      "asserted_values": [],
      "confidence": 0.95
    },
    {
      "id": "2",
      "type": "CONST",
      "text": "The LCG uses the constant 0xfff1.",
      "asserted_values": ["0xfff1"],
      "confidence": 0.95
    },
    {
      "id": "3",
      "type": "CF",
      "text": "The function uses a for loop to iterate over the input data.",
      "asserted_values": [],
      "confidence": 0.95
    },
    {
      "id": "4",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 0.95
    },
    {
      "id": "5",
      "type": "IO",
      "text": "Returns the computed checksum when len is greater than 0.",
      "asserted_values": [],
      "confidence": 0.95,
      "io": {
        "when": "len > 0",
        "returns": "computed checksum"
      }
    },
    {
      "id": "6",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when len is 0.",
      "asserted_values": [],
      "confidence": 0.95,
      "io": {
        "when": "len == 0",
        "returns": "VERA_ERR"
      }
    }
  ],
  "recovered_c": "uint64_t fn_03(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return VERA_ERR;\n  }\n\n  uint32_t a = 1;\n  uint32_t b = 0;\n\n  for (size_t i = 0; i < len; i++) {\n    a = (in[i] + a) % 0xfff1;\n    b = (b + a) % 0xfff1;\n  }\n\n  return (uint64_t)a | (uint64_t)b << 0x10;\n}"
}
